-- Expand before deploying RPC clients. Activation separately replaces triggers and ACLs.
create schema rate_security_private;
revoke all on schema rate_security_private from public,anon,authenticated,service_role;
grant usage on schema rate_security_private to authenticated;
create table rate_security_private.contexts(id bigint generated always as identity primary key,backend_pid integer not null,transaction_id bigint not null,kind text not null,source_id bigint,period_id bigint);
alter table rate_security_private.contexts enable row level security;
create policy internal_owner on rate_security_private.contexts for all to postgres using(true)with check(true);
revoke all on rate_security_private.contexts from public,anon,authenticated,service_role;

create function rate_security_private.actor()returns bigint language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select access_admin_private.actor()$$;
create function rate_security_private.allowed(k text,a text)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin
 perform rate_security_private.actor();if k is null or a is null or k not in('exchange-rates','consolidated-exchange-rates')or a not in('view','create','edit','delete')then return false;end if;
 return(a='view'and(public.app_is_admin()or exists(select 1 from public.role_access_matrix where role_id=public.app_active_role_id()and resource_key='legacy:all')))
 or exists(select 1 from public.role_access_matrix m where m.role_id=public.app_active_role_id()and m.resource_key='configuration:'||k and m.can_view and case a when'view'then true when'create'then m.can_create when'edit'then m.can_edit else m.can_delete end);
 exception when insufficient_privilege then return false;end$$;
create function rate_security_private.access(k text,a text)returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare u bigint:=rate_security_private.actor();begin if not rate_security_private.allowed(k,a)then raise exception using errcode='42501',message='Requiere permiso explicito de tasas.';end if;return u;end$$;
create function rate_security_private.member(target_id bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from public.user_subsidiaries where user_id=public.app_user_id()and subsidiary_id=target_id)$$;
create function rate_security_private.special(code text)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from public.role_permissions rp join public.permissions p using(permission_id)where rp.role_id=public.app_active_role_id()and p.code=special.code)$$;
create function rate_security_private.visible_daily(f bigint,t bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint;begin perform rate_security_private.actor();sid:=public.active_subsidiary_id();return public.app_is_admin()or exists(select 1 from public.subsidiaries s where s.subsidiary_id=sid and(s.currency_id in(f,t)or exists(select 1 from public.subsidiary_currencies sc where sc.subsidiary_id=sid and sc.currency_id in(f,t))));exception when insufficient_privilege then return false;end$$;
create function rate_security_private.visible_consolidated(h bigint,s bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform rate_security_private.actor();return rate_security_private.member(h)and rate_security_private.member(s);exception when insufficient_privilege then return false;end$$;
create function rate_security_private.global_scope(f bigint,t bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select rate_security_private.visible_daily(f,t)and not exists(select 1 from public.subsidiaries s where s.is_active and(s.currency_id in(f,t)or exists(select 1 from public.subsidiary_currencies c where c.subsidiary_id=s.subsidiary_id and c.currency_id in(f,t)))and not rate_security_private.member(s.subsidiary_id))$$;
create function rate_security_private.closed(pid bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select coalesce((select coalesce(p.is_closed,false)or coalesce(p.gl_closed,false)or coalesce(p.is_inactive,false)or coalesce(y.is_closed,false) from public.fiscal_periods p left join public.fiscal_years y using(fiscal_year_id)where p.fiscal_period_id=pid),true)$$;
create function rate_security_private.frozen(f bigint,t bigint,d date)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from public.fiscal_periods p join public.subsidiaries s using(subsidiary_id)where s.currency_id in(f,t)and p.end_date>=d and(coalesce(p.is_closed,false)or coalesce(p.gl_closed,false)or exists(select 1 from public.fiscal_years y where y.fiscal_year_id=p.fiscal_year_id and y.is_closed)))or exists(select 1 from public.consolidated_exchange_rates r join public.fiscal_periods p using(fiscal_period_id)where r.from_currency_id in(f,t)and r.to_currency_id in(f,t)and r.is_locked and p.end_date>=d)$$;
create function rate_security_private.positive(n numeric)returns boolean language sql immutable set search_path=pg_catalog,public,pg_temp as $$select n is not null and n::text not in('NaN','Infinity','-Infinity')and n>0$$;
create function rate_security_private.enter(kind text,source_id bigint default null,period_id bigint default null)returns bigint language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare cid bigint;begin insert into rate_security_private.contexts(backend_pid,transaction_id,kind,source_id,period_id)values(pg_backend_pid(),txid_current(),kind,source_id,period_id)returning id into cid;return cid;end$$;
create function rate_security_private.has_context(k text,s bigint default null,p bigint default null)returns boolean language sql volatile security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from rate_security_private.contexts c where c.backend_pid=pg_backend_pid()and c.transaction_id=txid_current()and c.kind=k and c.source_id is not distinct from s and c.period_id is not distinct from p)$$;

create function rate_security_private.sync(month text default null,source bigint default null,pid bigint default null,source_currency bigint default null,since date default null,strict_missing boolean default false)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare h bigint:=public.consolidation_holding_subsidiary_id();usd bigint;r record;existing public.consolidated_exchange_rates;closing numeric;average numeric;historical numeric;cid bigint;created_n int:=0;updated_n int:=0;missing_n int:=0;protected_n int:=0;conflict_n int:=0;
begin if month is not null and month!~'^[0-9]{4}-(0[1-9]|1[0-2])$'then raise exception using errcode='22023',message='Periodo invalido.';end if;perform pg_advisory_xact_lock(793150,1);perform pg_advisory_xact_lock(793154,1);select currency_id into usd from public.currencies where currency_code='USD';
 if h is null or usd is null then return jsonb_build_object('configured',false,'created',0,'updated',0);end if;
 for r in select fp.*,s.currency_id from public.fiscal_periods fp join public.subsidiaries s using(subsidiary_id)where s.is_active and s.currency_id<>usd and(month is null or to_char(fp.end_date,'YYYY-MM')=month)and(source is null or fp.subsidiary_id=source)and(pid is null or fp.fiscal_period_id=pid)and(source_currency is null or s.currency_id=source_currency)and(since is null or fp.end_date>=since)order by fp.fiscal_period_id loop
  select *into existing from public.consolidated_exchange_rates x where x.holding_subsidiary_id=h and x.source_subsidiary_id=r.subsidiary_id and x.period=to_char(r.end_date,'YYYY-MM')and x.from_currency_id=r.currency_id and x.to_currency_id=usd for update;
  if rate_security_private.closed(r.fiscal_period_id)or coalesce(existing.is_locked,false)then protected_n:=protected_n+1;continue;end if;
  if existing.rate_id is not null and existing.fiscal_period_id<>r.fiscal_period_id then conflict_n:=conflict_n+1;continue;end if;
  select case when e.from_currency_id=r.currency_id then e.spot_rate else 1/e.spot_rate end into closing from public.exchange_rates e where((e.from_currency_id=r.currency_id and e.to_currency_id=usd)or(e.from_currency_id=usd and e.to_currency_id=r.currency_id))and e.effective_date<=r.end_date order by effective_date desc,exchange_rate_id desc limit 1;
  select avg(case when e.from_currency_id=r.currency_id then e.spot_rate else 1/e.spot_rate end)into average from public.exchange_rates e where((e.from_currency_id=r.currency_id and e.to_currency_id=usd)or(e.from_currency_id=usd and e.to_currency_id=r.currency_id))and e.effective_date between r.start_date and r.end_date;
  select case when e.from_currency_id=r.currency_id then e.spot_rate else 1/e.spot_rate end into historical from public.exchange_rates e where((e.from_currency_id=r.currency_id and e.to_currency_id=usd)or(e.from_currency_id=usd and e.to_currency_id=r.currency_id))and e.effective_date<=r.start_date order by effective_date desc,exchange_rate_id desc limit 1;
  if closing is null or average is null then if strict_missing and existing.rate_id is not null then raise exception using errcode='55000',message='No puede dejar tasas consolidadas sin soporte diario.';end if;missing_n:=missing_n+1;continue;end if;historical:=coalesce(historical,closing);
  if not rate_security_private.positive(closing)or not rate_security_private.positive(average)or not rate_security_private.positive(historical)then raise exception using errcode='22023',message='Tasas de soporte invalidas.';end if;
  cid:=rate_security_private.enter('auto',r.subsidiary_id,r.fiscal_period_id);
  if existing.rate_id is null then insert into public.consolidated_exchange_rates(holding_subsidiary_id,source_subsidiary_id,period,from_currency_id,to_currency_id,fiscal_period_id,closing_rate,average_rate,historical_rate,is_locked)values(h,r.subsidiary_id,to_char(r.end_date,'YYYY-MM'),r.currency_id,usd,r.fiscal_period_id,closing,average,historical,false);created_n:=created_n+1;
  elsif row(existing.closing_rate,existing.average_rate,existing.historical_rate)is distinct from row(closing,average,historical)then update public.consolidated_exchange_rates set closing_rate=closing,average_rate=average,historical_rate=historical where rate_id=existing.rate_id;updated_n:=updated_n+1;end if;
  delete from rate_security_private.contexts where id=cid;
 end loop;return jsonb_build_object('configured',true,'holdingId',h,'period',month,'created',created_n,'updated',updated_n,'missingDailyRates',missing_n,'protected',protected_n,'periodConflicts',conflict_n);end$$;

create function rate_security_private.daily_dto(r public.exchange_rates)returns jsonb language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select to_jsonb(r)||jsonb_build_object('_revision',md5(to_jsonb(r)::text),'_actions',jsonb_build_object('canEdit',rate_security_private.allowed('exchange-rates','edit')and rate_security_private.global_scope(r.from_currency_id,r.to_currency_id)and not rate_security_private.frozen(r.from_currency_id,r.to_currency_id,r.effective_date),'canDelete',rate_security_private.allowed('exchange-rates','delete')and rate_security_private.global_scope(r.from_currency_id,r.to_currency_id)and not rate_security_private.frozen(r.from_currency_id,r.to_currency_id,r.effective_date)))$$;
create function rate_security_private.consolidated_dto(r public.consolidated_exchange_rates)returns jsonb language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select to_jsonb(r)||jsonb_build_object('_revision',md5(to_jsonb(r)::text),'fiscal_year',split_part(r.period,'-',1),'month_name',(array['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'])[(split_part(r.period,'-',2))::int],'_actions',jsonb_build_object('canEdit',not r.is_locked and not rate_security_private.closed(r.fiscal_period_id)and rate_security_private.allowed('consolidated-exchange-rates','edit')and rate_security_private.special('consolidation:rates:manage')and rate_security_private.visible_consolidated(r.holding_subsidiary_id,r.source_subsidiary_id),'canDelete',false))$$;
create function public.exchange_rate_catalog(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform rate_security_private.access(p_catalog,'view');if p_catalog='exchange-rates'then return(select coalesce(jsonb_agg(rate_security_private.daily_dto(r)order by r.effective_date desc,r.exchange_rate_id desc),'[]')from public.exchange_rates r where rate_security_private.visible_daily(r.from_currency_id,r.to_currency_id));end if;return(select coalesce(jsonb_agg(rate_security_private.consolidated_dto(r)order by r.rate_id),'[]')from public.consolidated_exchange_rates r where rate_security_private.visible_consolidated(r.holding_subsidiary_id,r.source_subsidiary_id));end$$;
create function public.exchange_rate_access(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform rate_security_private.access(p_catalog,'view');return jsonb_build_object('canView',true,'canCreate',p_catalog='exchange-rates'and rate_security_private.allowed(p_catalog,'create'),'canEdit',rate_security_private.allowed(p_catalog,'edit')and(p_catalog='exchange-rates'or rate_security_private.special('consolidation:rates:manage')),'canDelete',p_catalog='exchange-rates'and rate_security_private.allowed(p_catalog,'delete'),'canLock',p_catalog='consolidated-exchange-rates'and rate_security_private.special('consolidation:rates:lock'),'sourceCurrencies',(select coalesce(jsonb_agg(c.currency_code),'[]')from public.currencies c where c.currency_code in('DOP','CRC','GTQ','JMD','COP','ARS','NIO','PEN')and(rate_security_private.allowed('exchange-rates','create')or rate_security_private.allowed('exchange-rates','edit'))and rate_security_private.global_scope((select currency_id from public.currencies where currency_code='USD'),c.currency_id)),'references',jsonb_build_object('core/currencies',(select coalesce(jsonb_agg(jsonb_build_object('currency_id',currency_id,'currency_code',currency_code,'name',name)),'[]')from public.currencies),'organization/subsidiaries',(select coalesce(jsonb_agg(jsonb_build_object('subsidiary_id',subsidiary_id,'name',name)),'[]')from public.subsidiaries where rate_security_private.member(subsidiary_id)),'organization/accounting-periods',(select coalesce(jsonb_agg(jsonb_build_object('fiscal_period_id',fiscal_period_id,'period_name',period_name)),'[]')from public.fiscal_periods where rate_security_private.member(subsidiary_id))));end$$;

create function public.save_exchange_rate(p_catalog text,p_payload jsonb,p_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare u bigint:=rate_security_private.access(p_catalog,case when p_id is null then'create'else'edit'end);old_daily public.exchange_rates;old_con public.consolidated_exchange_rates;merged jsonb;f bigint;t bigint;d date;n numeric;cid bigint;rid bigint:=p_id;result jsonb;fields text[];
begin perform pg_advisory_xact_lock(793150,1);perform pg_advisory_xact_lock(793154,1);fields:=case p_catalog when'exchange-rates'then array['from_currency_id','to_currency_id','effective_date','spot_rate','_revision']else array['closing_rate','average_rate','historical_rate','is_locked','_revision']end;
 if jsonb_typeof(p_payload)is distinct from'object'or pg_column_size(p_payload)>64000 or exists(select 1 from jsonb_object_keys(p_payload)k where not k=any(fields))then raise exception using errcode='22023',message='Campos de tasa invalidos.';end if;
 if p_catalog='exchange-rates'then
  if rid is not null then select *into old_daily from public.exchange_rates where exchange_rate_id=rid for update;if not found or not rate_security_private.visible_daily(old_daily.from_currency_id,old_daily.to_currency_id)then raise exception using errcode='42501',message='Tasa no autorizada.';end if;if p_payload->>'_revision'is null or p_payload->>'_revision'is distinct from md5(to_jsonb(old_daily)::text)then raise exception using errcode='55000',message='La tasa cambio. Consulte nuevamente.';end if;end if;
  merged:=coalesce(to_jsonb(old_daily),'{}')||p_payload;f:=(merged->>'from_currency_id')::bigint;t:=(merged->>'to_currency_id')::bigint;
  if merged->>'effective_date'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'then raise exception using errcode='22023',message='Fecha invalida.';end if;begin d:=(merged->>'effective_date')::date;exception when invalid_datetime_format or datetime_field_overflow then raise exception using errcode='22023',message='Fecha invalida.';end;n:=(merged->>'spot_rate')::numeric;
  if f is null or t is null or f=t or d is null or not rate_security_private.positive(n)or not exists(select 1 from public.currencies where currency_id=f)or not exists(select 1 from public.currencies where currency_id=t)then raise exception using errcode='22023',message='Par, fecha o importe invalido.';end if;
  if not rate_security_private.global_scope(f,t)then raise exception using errcode='42501',message='Requiere acceso a todas las empresas afectadas por esta tasa global.';end if;
  if rate_security_private.frozen(f,t,d)then raise exception using errcode='55000',message='La tasa respalda periodos cerrados o tasas bloqueadas.';end if;
  if rid is not null and row(f,t,d)is distinct from row(old_daily.from_currency_id,old_daily.to_currency_id,old_daily.effective_date)then raise exception using errcode='55000',message='El par y la fecha de la tasa son inmutables.';end if;
  cid:=rate_security_private.enter('daily');if rid is null then insert into public.exchange_rates(from_currency_id,to_currency_id,effective_date,spot_rate)values(f,t,d,n)returning exchange_rate_id into rid;else update public.exchange_rates set spot_rate=n where exchange_rate_id=rid;end if;
  delete from rate_security_private.contexts where id=cid;select rate_security_private.daily_dto(r)into result from public.exchange_rates r where exchange_rate_id=rid;return result;
 end if;
 if rid is null or not rate_security_private.special('consolidation:rates:manage')then raise exception using errcode='42501',message='Mantenimiento consolidado no autorizado.';end if;
 select *into old_con from public.consolidated_exchange_rates where rate_id=rid for update;if not found or not rate_security_private.visible_consolidated(old_con.holding_subsidiary_id,old_con.source_subsidiary_id)then raise exception using errcode='42501',message='Tasa consolidada no autorizada.';end if;
 if p_payload->>'_revision'is null or p_payload->>'_revision'is distinct from md5(to_jsonb(old_con)::text)or old_con.is_locked or rate_security_private.closed(old_con.fiscal_period_id)then raise exception using errcode='55000',message='La tasa cambio o su periodo esta cerrado.';end if;
 merged:=to_jsonb(old_con)||p_payload;if(p_payload?'is_locked'and jsonb_typeof(p_payload->'is_locked')<>'boolean')or not rate_security_private.positive((merged->>'closing_rate')::numeric)or not rate_security_private.positive((merged->>'average_rate')::numeric)or not rate_security_private.positive((merged->>'historical_rate')::numeric)then raise exception using errcode='22023',message='Valores consolidados invalidos.';end if;
 if(merged->>'is_locked')::boolean and not rate_security_private.special('consolidation:rates:lock')then raise exception using errcode='42501',message='Requiere permiso explicito de bloqueo.';end if;
 cid:=rate_security_private.enter('manual',old_con.source_subsidiary_id,old_con.fiscal_period_id);update public.consolidated_exchange_rates set closing_rate=(merged->>'closing_rate')::numeric,average_rate=(merged->>'average_rate')::numeric,historical_rate=(merged->>'historical_rate')::numeric,is_locked=(merged->>'is_locked')::boolean where rate_id=rid;delete from rate_security_private.contexts where id=cid;select rate_security_private.consolidated_dto(r)into result from public.consolidated_exchange_rates r where rate_id=rid;return result;end$$;
create function public.delete_exchange_rate(p_id bigint,p_revision text)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.exchange_rates;cid bigint;begin perform rate_security_private.access('exchange-rates','delete');perform pg_advisory_xact_lock(793150,1);perform pg_advisory_xact_lock(793154,1);select *into r from public.exchange_rates where exchange_rate_id=p_id for update;if not found or not rate_security_private.global_scope(r.from_currency_id,r.to_currency_id)then raise exception using errcode='42501',message='Tasa no autorizada.';end if;if p_revision is null or p_revision is distinct from md5(to_jsonb(r)::text)or rate_security_private.frozen(r.from_currency_id,r.to_currency_id,r.effective_date)then raise exception using errcode='55000',message='La tasa cambio o tiene soporte protegido.';end if;cid:=rate_security_private.enter('daily');delete from public.exchange_rates where exchange_rate_id=p_id;delete from rate_security_private.contexts where id=cid;return true;end$$;
create function public.exchange_rate_source_context(p_from bigint,p_to bigint,p_date date)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.exchange_rates;begin perform rate_security_private.access('exchange-rates','view');if not rate_security_private.global_scope(p_from,p_to)then raise exception using errcode='42501',message='Tasa global no autorizada.';end if;select *into r from public.exchange_rates where from_currency_id=p_from and to_currency_id=p_to and effective_date=p_date;perform rate_security_private.access('exchange-rates',case when r.exchange_rate_id is null then'create'else'edit'end);return jsonb_build_object('id',r.exchange_rate_id,'revision',case when r.exchange_rate_id is null then null else md5(to_jsonb(r)::text)end);end$$;
create function public.ingest_official_exchange_rate(p_from bigint,p_to bigint,p_date date,p_rate numeric)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare cid bigint;r public.exchange_rates;begin
 if p_date is null or not rate_security_private.positive(p_rate)or not exists(select 1 from public.currencies where currency_id=p_from and currency_code='USD')or not exists(select 1 from public.currencies where currency_id=p_to and currency_code in('DOP','CRC','GTQ','JMD','COP','ARS','NIO','PEN'))then raise exception using errcode='22023',message='Ingesta oficial invalida.';end if;
 perform pg_advisory_xact_lock(793150,1);perform pg_advisory_xact_lock(793154,1);if rate_security_private.frozen(p_from,p_to,p_date)then raise exception using errcode='55000',message='La fecha de ingesta tiene soporte cerrado.';end if;
 cid:=rate_security_private.enter('daily');insert into public.exchange_rates(from_currency_id,to_currency_id,effective_date,spot_rate)values(p_from,p_to,p_date,p_rate)on conflict(from_currency_id,to_currency_id,effective_date)do update set spot_rate=excluded.spot_rate returning *into r;delete from rate_security_private.contexts where id=cid;return to_jsonb(r);end$$;

revoke all on all functions in schema rate_security_private from public,anon,authenticated,service_role;
grant execute on function rate_security_private.visible_daily(bigint,bigint),rate_security_private.visible_consolidated(bigint,bigint)to authenticated;
revoke all on function public.exchange_rate_catalog(text),public.exchange_rate_access(text),public.save_exchange_rate(text,jsonb,bigint),public.delete_exchange_rate(bigint,text),public.exchange_rate_source_context(bigint,bigint,date),public.ingest_official_exchange_rate(bigint,bigint,date,numeric)from public,anon,authenticated,service_role;
grant execute on function public.exchange_rate_catalog(text),public.exchange_rate_access(text),public.save_exchange_rate(text,jsonb,bigint),public.delete_exchange_rate(bigint,text),public.exchange_rate_source_context(bigint,bigint,date)to authenticated;
grant execute on function public.ingest_official_exchange_rate(bigint,bigint,date,numeric)to service_role;
notify pgrst,'reload schema';
